import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_includes_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_each_transcript_equally():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_trailing_window():
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 4) == 6


def test_parse_whitespace_comments_and_flags():
    lines = ["   # ignored", "", " \t", " x , 2 , 0 ", " y , 3 , ", "z,4,1"]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": 2, "flagged": False},
        {"id": "y", "day": 3, "flagged": None},
        {"id": "z", "day": 4, "flagged": True},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,Monday,1"])
def test_parse_errors_include_physical_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", "  # ignored", "x,1,1", bad_line])


def test_dedupe_keeps_last_record_for_duplicate_id_then_sorts():
    events = parse_transcript_log(["b,9,1", "c,2,0", "b,2,0", "z,1,1"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_daily_counts_include_gaps_and_ignore_outside_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,3,1", "d,3,1", "e,4,1"])
    assert daily_flag_counts(events, 1, 3) == [1, 0, 2]
    assert daily_flag_counts(events, 3, 1) == []


def test_summary_counts_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["x,1,1", "y,4,1", "z,5,0"]), "b": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert monitor_summary({"b": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_reports_handle_ties_order_and_empty_groups():
    groups = {"z": [{"flagged": True}], "b": [{"flagged": True}], "a": [{"flagged": False}], "c": []}
    assert top_flagged_groups(groups, 2) == ["b", "z"]
    assert top_flagged_groups(groups, 5) == ["b", "z", "a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", 1.0), ("c", None), ("z", 1.0)]


def test_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([1, -1, 1, 2, 0, 1]) == 2
    assert longest_flag_streak([]) == 0
